  async function members(){const students=await api(`/api/classes/${select.value}/users`),users=[{id:state.user.id,first_name:state.user.first_name,username:state.user.username,teacher:true},...students];$('#project-members').innerHTML=`<strong>Projektmitglieder und Gesamtprojektleitung</strong><div class="member-list">${users.map((u,i)=>`<label class="member"><span><input type="checkbox" name="member" value="${u.id}" checked> ${esc(u.first_name)} <small>${u.teacher?'Lehrkraft':esc(u.username)}</small></span><span><input type="radio" name="lead" value="${u.id}" ${i===0?'checked':''}> Leitung</span></label>`).join('')}</div>`}select.addEventListener('change',members);await members();
