  const existingBoard=$('#board');if(existingBoard)ui.scrollLeft=existingBoard.scrollLeft;
  $('#project-tab').innerHTML=`<div class="filters"><input id="task-search" placeholder="Aufgaben durchsuchen"><select id="team-filter"><option value="">Alle Teams</option>${p.teams.filter(t=>t.status==='active').map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><select id="phase-filter"><option value="">Alle Phasen</option><option value="none">Ohne Phase</option>${p.phases.map(ph=>`<option value="${ph.id}">${esc(ph.name)}</option>`).join('')}</select><select id="assignee-filter"><option value="">Alle Verantwortlichen</option><option value="none">Noch zu verteilen</option>${p.members.map(member=>`<option value="${member.id}">${esc(member.first_name)}</option>`).join('')}</select>${p.can_manage||isAnyTeamLead(p)?'<button class="button primary" id="add-task">Aufgabe anlegen</button>':''}${p.can_manage?'<button class="button" id="edit-statuses">Status bearbeiten</button>':''}</div><div id="board" class="board"></div>`;
