function adminViewTabs(active){return state.user.is_owner?`<div class="tabs admin-tabs"><a class="${active==='teachers'?'active':''}" href="#/admin/teachers">Lehrkraftzugänge</a><a class="${active==='licenses'?'active':''}" href="#/admin/licenses">Bestellungen &amp; Lizenzen</a><a class="${active==='products'?'active':''}" href="#/admin/products">Produkte &amp; Preise</a><a class="${active==='support'?'active':''}" href="#/admin/support">Supportzugriff</a><a class="${active==='account'?'active':''}" href="#/admin/account">Eigenes Konto</a></div>`:`<div class="tabs admin-tabs"><a class="${active==='classes'?'active':''}" href="#/admin">Klassen</a><a class="${active==='users'?'active':''}" href="#/admin/users">Alle Zugänge</a><a class="${active==='help'?'active':''}" href="#/admin/help">Hilfe anfordern</a><a class="${active==='account'?'active':''}" href="#/admin/account">Eigenes Konto</a></div>`}
