  $('#archive-teacher',dlg)?.addEventListener('click',async event=>{event.preventDefault();try{await api(`/api/teachers/${teacher.id}/archive`,{method:'POST',body:{}});closeDialog();toast('Der Lehrkraftzugang wurde archiviert.');route()}catch(error){toast(error.message,true)}});
  $('#restore-teacher',dlg)?.addEventListener('click',async event=>{event.preventDefault();try{await api(`/api/teachers/${teacher.id}/restore`,{method:'POST',body:{}});closeDialog();toast('Der Lehrkraftzugang wurde reaktiviert.');route()}catch(error){toast(error.message,true)}});
