function teacherDialog(licenses,teacher=null,products=[]){
  const editing=Boolean(teacher);
  const current=teacher?.licenses.find(item=>['active','draft','suspended'].includes(item.status));
  const existingOptions=licenses.filter(item=>['active','draft','suspended'].includes(item.status)&&(item.used_seats<item.seat_limit||item.id===current?.id));
  const dlg=openDialog(editing?`Lehrkraft ${teacher.first_name} bearbeiten`:'Lehrkraft anlegen',`<form id="teacher-form" class="stack">
    <div class="form-grid teacher-identity-grid"><label>Name<input name="first_name" value="${esc(teacher?.first_name||'')}" maxlength="80" required></label><label>Benutzername<input name="username" value="${esc(teacher?.username||'lehrkraft_')}" maxlength="50" autocomplete="off" required><small class="muted">Muss mit „lehrkraft_“ beginnen.</small></label></div>
    <label>E-Mail-Adresse<input name="email" type="email" value="${esc(teacher?.email||'')}" maxlength="254" required><small class="muted">An diese Adresse können die Initialzugangsdaten gesendet werden.</small></label>
    ${editing?`<label class="toggle-row"><input type="checkbox" name="active" ${teacher.active?'checked':''}> Konto technisch aktiviert</label>`:''}
    <section class="license-assignment-panel"><strong>Lizenzzuordnung</strong><p class="muted">Wählen Sie die Lizenz für diesen Zugang. Beim Wechsel wird eine bisherige aktuelle Zuordnung automatisch ersetzt.</p><label>Zuordnung ändern<select name="license_selection">
      <option value="none" ${current?'':'selected'}>Noch nicht freischalten / keine aktive Lizenz</option>
      <optgroup label="Neue Lizenz aus Produktkatalog">${products.filter(product=>product.active).map(product=>`<option value="new-product:${esc(product.product_key)}">${esc(product.name)} · ${euro(product.amount_cents)}</option>`).join('')}</optgroup>
      ${existingOptions.length?`<optgroup label="Vorhandene Lizenz mit freiem Platz">${existingOptions.map(item=>`<option value="existing:${item.id}" ${item.id===current?.id?'selected':''}>${esc(item.organization||item.customer_name)} · ${esc(LICENSE_PLANS[item.plan]||item.plan)} · ${item.used_seats}/${item.seat_limit} Plätze · ${esc(LICENSE_STATUS[item.status]||item.status)}</option>`).join('')}</optgroup>`:''}
    </select></label></section>
    <fieldset class="team-assignment new-license-details hidden"><legend>Daten der neuen Lizenz</legend><div class="stack"><div class="form-grid"><label>Ansprechperson<input name="license_customer_name" maxlength="120"></label><label>Schule / Organisation<input name="license_organization" maxlength="160"></label></div><label>E-Mail für die Rechnung<input name="license_email" type="email" maxlength="254"></label><fieldset class="billing-address-fields"><legend>Rechnungsanschrift</legend><div class="billing-address-grid"><label>Straße und Hausnummer<input name="license_billing_street" maxlength="500" autocomplete="street-address"></label><label>PLZ<input name="license_billing_postal_code" maxlength="10" inputmode="numeric" autocomplete="postal-code"></label><label>Ort<input name="license_billing_city" maxlength="160" autocomplete="address-level2"></label></div><small class="muted">Kann auch später in der Lizenz ergänzt werden.</small></fieldset></div></fieldset>
    <div class="info-box">Eine Lehrkraft kann sich nur anmelden, wenn das Konto technisch aktiviert und eine aktive, noch gültige Lizenz zugeordnet ist.${editing&&teacher.last_login_at?' Das persönliche Kennwort kann nur die Lehrkraft selbst ändern.':''}</div>
  </form>`,editing?`<button class="button" value="cancel">Abbrechen</button><button class="button danger" id="manage-teacher-removal" value="none">${teacher.archived_at?'Archiv verwalten':'Archivieren oder löschen'}</button>${teacher.archived_at?'':teacher.last_login_at?'':'<button class="button" id="reset-teacher-password" value="none">Neues Initialkennwort</button>'}${teacher.archived_at?'':'<button class="button primary" id="save-teacher" value="none">Speichern</button>'}`:'<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-teacher" value="none">Lehrkraft anlegen</button>');
  const form=$('#teacher-form',dlg);
  if(teacher?.archived_at)$$('input,select,textarea',form).forEach(control=>control.disabled=true);
  const usernameInput=$('[name=username]',form);usernameInput.addEventListener('blur',()=>{if(!usernameInput.value.startsWith('lehrkraft_'))usernameInput.value=`lehrkraft_${usernameInput.value.replace(/^lehrkraft_*/,'')}`});
  const licenseSelect=$('[name=license_selection]',form),licenseDetails=$('.new-license-details',form);
  const updateLicenseDetails=()=>licenseDetails.classList.toggle('hidden',!licenseSelect.value.startsWith('new'));
  licenseSelect.addEventListener('change',updateLicenseDetails);updateLicenseDetails();
  const payload=()=>({first_name:field(form,'first_name')?.trim(),username:field(form,'username')?.trim(),email:field(form,'email')?.trim(),license_selection:licenseSelect.value,license_customer_name:field(form,'license_customer_name'),license_organization:field(form,'license_organization'),license_email:field(form,'license_email'),license_billing_address:billingAddress(form,'license_'),...(editing?{active:$('[name=active]',form).checked}:{})});
  $('#save-teacher',dlg)?.addEventListener('click',async event=>{event.preventDefault();try{const data=payload();const result=await api(editing?`/api/teachers/${teacher.id}`:'/api/teachers',{method:editing?'PATCH':'POST',body:data});closeDialog();if(result.initial_password)teacherCredentialsDialog(result.id,data.first_name,data.username,result.email,result.initial_password);else{route();toast('Lehrkraft wurde aktualisiert.')}}catch(error){toast(error.message,true)}});
  $('#manage-teacher-removal',dlg)?.addEventListener('click',event=>{event.preventDefault();closeDialog();teacherRemovalDialog(teacher)});
  $('#reset-teacher-password',dlg)?.addEventListener('click',async event=>{event.preventDefault();if(!confirm(`Für ${teacher.first_name} ein neues Initialkennwort erzeugen und alle laufenden Sitzungen beenden?`))return;try{const data={...payload(),reset_password:true};const result=await api(`/api/teachers/${teacher.id}`,{method:'PATCH',body:data});closeDialog();teacherCredentialsDialog(teacher.id,data.first_name,data.username,result.email,result.initial_password)}catch(error){toast(error.message,true)}});
}
